using SpikeInv012A;
using SpikeInv012A.Core;
using System.Text.Json;

var tests = new (string Name, Action Body)[]
{
    ("manual Ready never expires", () => { var x = New(); x.Clock.Now = 1_000_000; x.Core.Poll(); Eq(Stage.ManualReady, x.Core.Stage); }),
    ("save wait expires without ticker", () => { var x = New(); x.Core.SaveEntered(true, true); x.Clock.Now = 30_000; x.Core.Poll(); Eq(Outcome.SaveTimeout, x.Core.Outcome); Eq(0L, x.Core.Ticks); }),
    ("ticker unattached capture expires", () => { var x = Capture(); x.Clock.Now = 30_000; x.Core.Poll(); Eq(Outcome.CaptureTimeout, x.Core.Outcome); Eq(false, x.Sink.Records.Any(r => r.Event == "ticker-attached")); }),
    ("baseline then never ready", () => { var x = Capture(); for (int i=0;i<35;i++) x.Core.Tick(i, Reject("handPresent"), false); x.Clock.Now=30_000; x.Core.Poll(); Eq(Outcome.CaptureTimeout, x.Core.Outcome); Eq(true, x.Sink.Records.Any(r => r.Name == "handPresent")); }),
    ("first tick provenance", () => { var x=Capture(); x.Core.TickerAttached(true,true); x.Core.Tick(1,Reject("phaseIsPlay"),true); Eq(1, x.Sink.Records.Count(r=>r.Event=="first-tick")); Eq(true, x.Sink.Records.Single(r=>r.Event=="ticker-attached").Flag); }),
    ("precheck PASS requires actual frame and evidence", () => { var x=New(); x.Core.Precheck(true); x.Core.TickerAttached(true,true); Eq(false,PrebusinessGate.ReadyToAnnounce(x.Core)); Eq(false,x.Sink.Records.Any(r=>r.Event=="first-tick")); x.Core.Tick(1,[],false); Eq(true,PrebusinessGate.ReadyToAnnounce(x.Core)); Eq(1,x.Sink.Records.Count(r=>r.Event=="first-tick")); }),
    ("failed first-tick evidence cannot announce PASS", () => { var x=New(); x.Core.Precheck(true); x.Core.TickerAttached(true,true); x.Sink.FailEvent="first-tick"; x.Core.Tick(1,[],false); Eq(false,PrebusinessGate.ReadyToAnnounce(x.Core)); Eq(false,x.Core.EvidenceComplete); }),
    ("terminal cannot announce late precheck PASS", () => { var x=New(); x.Core.Precheck(true); x.Core.TickerAttached(true,true); x.Core.Tick(1,[],false); x.Core.ObserverFailed("InvalidOperationException","ticker.tick"); Eq(false,PrebusinessGate.ReadyToAnnounce(x.Core)); }),
    ("every required field can reject", () => { foreach (var name in TestData.Names) { var x=Capture(); x.Core.Tick(1,Reject(name),false); Eq(name,x.Sink.Records.Single(r=>r.Event=="reject").Name); } }),
    ("observer exception", () => { var x=Capture(); x.Core.ObserverFailed("InvalidOperationException","ticker.tick"); Eq(Outcome.ObserverFailure,x.Core.Outcome); Eq(true,x.Sink.Records.Any(r=>r.ExceptionType=="InvalidOperationException")); }),
    ("evidence write failure invalidates no-tick", () => { var x=New(fail:true); x.Core.SaveEntered(true,true); x.Clock.Now=30_000; x.Core.Poll(); Eq(false,x.Core.EvidenceComplete); }),
    ("precheck or arm evidence failure blocks Ready", () => { var x=New(); x.Sink.FailEvent="precheck"; x.Core.Precheck(true); Eq(Outcome.EvidenceFailure,x.Core.Outcome); var y=New(); y.Sink.FailEvent="manual-ready"; y.Core.Arm(); Eq(Outcome.EvidenceFailure,y.Core.Outcome); }),
    ("transient first-tick write loss cannot seal capture success", () => { var x=Capture(); x.Sink.FailEvent="first-tick"; for(int i=0;i<30;i++) x.Core.Tick(i,Ready(),false); Eq(Outcome.EvidenceFailure,x.Core.Outcome); Eq(false,x.Sink.Records.Any(r=>r.Event=="capture-ready")); Eq(true,x.Sink.Records.Any(r=>r.Event=="terminal")); }),
    ("save stage-start loss stops business lane", () => { var x=New(); x.Sink.FailEvent="stage-start"; x.Core.SaveEntered(true,true); x.Core.SaveCompleted(true,false); x.Core.SaveEntered(true,true); Eq(Outcome.EvidenceFailure,x.Core.Outcome); Eq(1,x.Sink.Records.Count(r=>r.Event=="terminal")); Eq(false,x.Sink.Records.Any(r=>r.Event is "save-entry" or "save-complete")); Eq("terminal",x.Sink.Records.Last().Event); x.Core.Writer("NGame.Quit",false,null); Eq("writer-summary",x.Sink.Records.Last().Event); Eq(1,x.Sink.Records.Count(r=>r.Event=="terminal")); }),
    ("seal stage-start loss stops business lane", () => { var x=New(); x.Core.SaveEntered(true,true); x.Sink.FailEvent="stage-start"; x.Core.SaveCompleted(true,false); x.Core.SealCheckpointMetadata(); Eq(Outcome.EvidenceFailure,x.Core.Outcome); Eq(1,x.Sink.Records.Count(r=>r.Event=="terminal")); Eq(true,x.Sink.Records.Any(r=>r.Event=="save-entry")); Eq(false,x.Sink.Records.Any(r=>r.Event=="save-complete")); Eq("terminal",x.Sink.Records.Last().Event); }),
