    ("identity refusal creates no attempt or business call", () => { var dir=Path.Combine(Path.GetTempPath(),"spikeinv012a-gate-"+Guid.NewGuid().ToString("N")); var logs=new List<string>(); int attempts=0,business=0; foreach(var (ids,manager,profile,modded) in new (string?[],bool,int?,bool)[] { ([],true,1,true), (["SPIKEINV012A","other"],true,1,true), ([null,"SPIKEINV012A"],true,1,true), (["other"],true,1,true), (["SPIKEINV012A"],false,null,true), (["SPIKEINV012A"],true,2,true), (["SPIKEINV012A"],true,1,false) }) { var core=PrebusinessGate.Open(() => PrebusinessGate.ExactIdentity(ids,manager,profile,modded), () => { attempts++; return new DiagnosticCore(new FakeClock(),new EvidenceSink(dir,"attempt"),"attempt","process","boot"); }, logs.Add); if(core is not null) { business++; core.Arm(); } Eq(true,core is null); } Eq(0,attempts); Eq(0,business); Eq(false,Directory.Exists(dir)); Eq(7,logs.Count); Eq(true,logs.All(x=>x==PrebusinessGate.BlockedMarker)); Eq(false,string.Join(';',logs).Contains(dir,StringComparison.Ordinal)); }),
    ("identity exception blocks without files or payload log", () => { var dir=Path.Combine(Path.GetTempPath(),"spikeinv012a-gate-"+Guid.NewGuid().ToString("N")); var logs=new List<string>(); int attempts=0; var core=PrebusinessGate.Open(() => throw new InvalidOperationException("private/path"), () => { attempts++; return new DiagnosticCore(new FakeClock(),new EvidenceSink(dir,"attempt"),"attempt","process","boot"); }, logs.Add); Eq(true,core is null); Eq(0,attempts); Eq(false,Directory.Exists(dir)); Eq(PrebusinessGate.BlockedMarker,logs.Single()); Eq(false,logs.Single().Contains("private",StringComparison.Ordinal)); }),
    ("accepted identity missing ticker owner seals prebusiness", () => { var dir=Path.Combine(Path.GetTempPath(),"spikeinv012a-owner-"+Guid.NewGuid().ToString("N")); try { var logs=new List<string>(); var core=PrebusinessGate.Open(() => PrebusinessGate.ExactIdentity(["SPIKEINV012A"],true,1,true), () => new DiagnosticCore(new FakeClock(),new EvidenceSink(dir,"attempt"),"attempt","process","boot"), logs.Add)!; core.Precheck(true); int business=0; bool attached=PrebusinessGate.RequireTickerOwner(core, () => false, () => logs.Add("SPIKEINV012A PROBE_TERMINAL_STOP_INPUT")); if(attached) { business++; core.Arm(); } Eq(false,attached); Eq(0,business); Eq(Outcome.PrebusinessOwnerUnavailable,core.Outcome); Eq(1,logs.Count); Eq("SPIKEINV012A PROBE_TERMINAL_STOP_INPUT",logs.Single()); var files=Directory.GetFiles(Path.Combine(dir,"SPIKEINV012A","attempt"),"*.json"); Eq(3,files.Length); Eq(true,files.Any(f=>File.ReadAllText(f).Contains("\"Event\":\"terminal\"",StringComparison.Ordinal))); Eq(false,files.Any(f=>File.ReadAllText(f).Contains("\"Event\":\"manual-ready\"",StringComparison.Ordinal))); Eq(false,files.Any(f=>File.ReadAllText(f).Contains("\"Event\":\"save-entry\"",StringComparison.Ordinal))); } finally { DeleteTestDirectory(dir); } }),
    ("ticker attach exception also terminates before business", () => { var x=New(); x.Core.Precheck(true); int business=0,logs=0; var attached=PrebusinessGate.RequireTickerOwner(x.Core, () => throw new InvalidOperationException("private/path"), () => logs++); if(attached) { business++; x.Core.Arm(); } Eq(false,attached); Eq(0,business); Eq(1,logs); Eq(Outcome.PrebusinessOwnerUnavailable,x.Core.Outcome); Eq(1,x.Sink.Records.Count(r=>r.Event=="terminal")); Eq(false,x.Sink.Records.Any(r=>r.Event=="manual-ready")); }),
    ("deadline before exact and after", () => { var a=Capture(); a.Clock.Now=29_999; a.Core.Poll(); Eq(Stage.Capture,a.Core.Stage); var b=Capture(); b.Clock.Now=30_000; b.Core.Poll(); Eq(Outcome.CaptureTimeout,b.Core.Outcome); var c=Capture(); c.Clock.Now=30_001; c.Core.Poll(); Eq(Outcome.CaptureTimeout,c.Core.Outcome); }),
    ("exact expiry beats completion", () => { var x=New(); x.Core.SaveEntered(true,true); x.Clock.Now=30_000; x.Core.SaveCompleted(true,false); Eq(Outcome.SaveTimeout,x.Core.Outcome); }),
    ("late callback cannot revive", () => { var x=Capture(); x.Clock.Now=30_000; x.Core.Poll(); x.Core.Tick(1,Ready(),true); x.Core.SaveCompleted(true,false); Eq(Outcome.CaptureTimeout,x.Core.Outcome); }),
    ("terminal single commit and stale timer", () => { var x=Capture(); var generation=x.Core.Deadline!.Value.Generation; x.Core.ObserverFailed("Exception","ticker.tick"); x.Core.Poll(generation); x.Core.ObserverFailed("Exception","ticker.tick"); Eq(1,x.Sink.Records.Count(r=>r.Event=="terminal")); }),
    ("deadline completion race", () => { for(int i=0;i<100;i++) { var x=New(); x.Core.SaveEntered(true,true); x.Clock.Now=30_000; Parallel.Invoke(() => x.Core.Poll(), () => x.Core.SaveCompleted(true,false)); Eq(Outcome.SaveTimeout,x.Core.Outcome); Eq(1,x.Sink.Records.Count(r=>r.Event=="terminal")); } }),
    ("save fault and cancellation distinguished", () => { var x=New(); x.Core.SaveEntered(true,true); x.Core.SaveCompleted(false,false); Eq(Outcome.SaveFault,x.Core.Outcome); var y=New(); y.Core.SaveEntered(true,true); y.Core.SaveCompleted(false,true); Eq(Outcome.SaveCanceled,y.Core.Outcome); }),
    ("restart process provenance", () => { var x=New(); x.Core.MarkRestart("other-process",Stage.Capture); Eq(Outcome.RestartIncomplete,x.Core.Outcome); var y=New(); y.Core.MarkRestart("process",Stage.Capture); Eq(Stage.ManualReady,y.Core.Stage); }),
    ("writer entered without return", () => { var x=New(); x.Core.Writer("CombatReplayWriter.WriteReplay",true,true); x.Core.Writer("NRun.Notification",false,null); Eq(true,x.Sink.Records.Last(r=>r.Event=="writer-summary").Summary!.Contains("CombatReplayWriter.WriteReplay:1:0",StringComparison.Ordinal)); }),
    ("recording flags false and true", () => { var x=New(); x.Core.Writer("RunManager.CleanUp",true,false); x.Core.Writer("RunManager.CleanUp",false,true); x.Core.Writer("NRun.Notification",false,null); Eq(true,x.Sink.Records.Last(r=>r.Event=="writer-summary").Summary!.Contains("RunManager.CleanUp:1:1:1:2:False:True",StringComparison.Ordinal)); }),
    ("no writer evidence stays empty", () => { var x=Capture(); x.Core.Writer("NGame.Quit",true,null); x.Core.Writer("NGame.Quit",false,null); Eq(false,x.Sink.Records.Last(r=>r.Event=="writer-summary").Summary!.Contains("SettingsSaveManager",StringComparison.Ordinal)); }),
    ("writer after capture terminal is separate audit lane", () => { var x=Capture(); x.Clock.Now=30_000; x.Core.Poll(); x.Core.Writer("SettingsSaveManager.SaveSettings",true,null); x.Core.Writer("NGame.Quit",false,null); Eq(Outcome.CaptureTimeout,x.Core.Outcome); Eq(true,x.Sink.Records.Last(r=>r.Event=="writer-summary").Summary!.Contains("SettingsSaveManager.SaveSettings:1:0",StringComparison.Ordinal)); }),
    ("duplicate save callback ignored", () => { var x=New(); x.Core.SaveEntered(true,true); x.Core.SaveCompleted(true,false); x.Core.SaveCompleted(false,false); Eq(Stage.CheckpointSeal,x.Core.Stage); }),
    ("thirty consecutive frames", () => { var x=Capture(); for(int i=0;i<29;i++) x.Core.Tick(i,Ready(),false); Eq(Stage.Capture,x.Core.Stage); x.Core.Tick(29,Ready(),false); Eq(Outcome.CaptureComplete,x.Core.Outcome); }),
    ("frame gap resets quiet count", () => { var x=Capture(); for(int i=0;i<29;i++) x.Core.Tick(i,Ready(),false); x.Core.Tick(31,Ready(),false); Eq(Stage.Capture,x.Core.Stage); }),
    ("checkpoint seal has own deadline", () => { var x=New(); x.Core.SaveEntered(true,true); x.Core.SaveCompleted(true,false); x.Clock.Now=30_000; x.Core.SealCheckpointMetadata(); Eq(Outcome.SealTimeout,x.Core.Outcome); }),
    ("malformed field and token blocked", () => { var x=Capture(); x.Core.Tick(1,[new("seed",FieldStatus.False)],false); Eq(Outcome.ObserverFailure,x.Core.Outcome); var y=Capture(); y.Core.ObserverFailed("secret message / path","bad/site"); Eq("invalid_token",y.Sink.Records.First(r=>r.Event=="observer-exception").ExceptionType); y.Core.Writer("C:\\private\\latest.mcr",true,true); var json=JsonSerializer.Serialize(x.Sink.Records)+JsonSerializer.Serialize(y.Sink.Records); Eq(false,json.Contains("secret",StringComparison.Ordinal)); Eq(false,json.Contains("C:\\private",StringComparison.Ordinal)); Eq(false,json.Contains("\"seed\"",StringComparison.Ordinal)); }),
    ("capture seal survives evidence quota", () => { var dir=Path.Combine(Path.GetTempPath(),"spikeinv012a-test-"+Guid.NewGuid().ToString("N")); try { var sink=new EvidenceSink(dir,"attempt"); var clock=new FakeClock(); var core=new DiagnosticCore(clock,sink,"attempt","process","boot"); core.Precheck(true); core.TickerAttached(true,true); core.Arm(); core.SaveEntered(true,true); core.SaveCompleted(true,false); core.SealCheckpointMetadata(); core.Tick(0,Reject("handPresent"),false); for(int i=1;i<=30;i++) core.Tick(i,Ready(),false); Eq(Outcome.CaptureComplete,core.Outcome); var contents=Directory.GetFiles(Path.Combine(dir,"SPIKEINV012A","attempt"),"*.json").Select(File.ReadAllText).ToArray(); Eq(true,contents.Any(s=>s.Contains("\"Event\":\"capture-ready\"",StringComparison.Ordinal))); Eq(true,contents.Length<=16); } finally { DeleteTestDirectory(dir); } }),
    ("sink cap create-new and payload whitelist", () => { var dir=Path.Combine(Path.GetTempPath(),"spikeinv012a-test-"+Guid.NewGuid().ToString("N")); try { var sink=new EvidenceSink(dir,"attempt"); var r=new Record(1,"attempt","process","boot","heartbeat",Stage.Capture,0,1,0); for(int i=0;i<25;i++) Eq(true,sink.TryWrite(r)); Eq(true,sink.TryWrite(r with { Event="writer-summary" })); Eq(true,sink.TryWrite(r with { Event="writer-summary" })); Eq(true,sink.TryWrite(r,true)); Eq(15,Directory.GetFiles(Path.Combine(dir,"SPIKEINV012A","attempt"),"*.json").Length); Eq(false,sink.TryWrite(r,true)); } finally { DeleteTestDirectory(dir); } })
};
int passed=0;
foreach (var (name,body) in tests)
{
    try { body(); Console.WriteLine("PASS " + name); passed++; }
    catch (Exception ex) { Console.Error.WriteLine("FAIL " + name + " " + ex.GetType().Name + ": " + ex.Message); return 1; }
}
Console.WriteLine($"PASS {passed}/{tests.Length}");
return 0;

static (DiagnosticCore Core, FakeClock Clock, MemoryEvidence Sink) New(bool fail=false)
{ var clock=new FakeClock(); var sink=new MemoryEvidence{Fail=fail}; return (new DiagnosticCore(clock,sink,"attempt","process","boot"),clock,sink); }
static (DiagnosticCore Core, FakeClock Clock, MemoryEvidence Sink) Capture()
{ var x=New(); x.Core.SaveEntered(true,true); x.Core.SaveCompleted(true,false); x.Core.SealCheckpointMetadata(); Eq(Stage.Capture,x.Core.Stage); return x; }
static FieldSample[] Ready() => TestData.Names.Select(n=>new FieldSample(n,FieldStatus.True)).ToArray();
static FieldSample[] Reject(string name) => TestData.Names.Select(n=>new FieldSample(n,n==name?FieldStatus.False:FieldStatus.True)).ToArray();
static void Eq<T>(T expected,T actual) { if(!EqualityComparer<T>.Default.Equals(expected,actual)) throw new Exception($"expected {expected}; actual {actual}"); }
static void DeleteTestDirectory(string dir)
{
    var full = Path.GetFullPath(dir);
    var temp = Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;
    if (!full.StartsWith(temp + "spikeinv012a-", StringComparison.OrdinalIgnoreCase) ||
        full.Length <= temp.Length + "spikeinv012a-".Length) throw new InvalidOperationException("unsafe test directory");
    if (Directory.Exists(full)) Directory.Delete(full, true);
}
static class TestData { public static readonly string[] Names = ["managerPresent","statePresent","singlePlayerPresent","playerCombatStatePresent","handPresent",
    "combatPresent","executorPresent","roomPresent","combatIsInProgress","combatIsNotOverOrEnding","combatIsNotPaused",
    "runIsNotPaused","playerActionsEnabled","isPartOfPlayerTurn","phaseIsPlay","executorIsNotRunning",
    "executorIsNotPaused","currentActionIsNull","currentRunNodePresent","targetIdentityStable"]; }
sealed class FakeClock : IClock { public long Now { get; set; } public long Frequency => 1000; }
sealed class MemoryEvidence : IEvidence { public bool Fail; public string? FailEvent; public List<Record> Records {get;}=[]; public bool TryWrite(Record record,bool final=false) { if(Fail || record.Event==FailEvent) { FailEvent=null; return false; } Records.Add(record); return true; } }

